<template>
  <section class="dashboard-page">
    <div class="page-heading"><div><p class="overline">BUSINESS INTELLIGENCE</p><h1>ダッシュボード</h1><p>EC運営の重要指標を、ひとつの画面で把握します。</p></div><div class="controls"><el-date-picker v-model="pickerRange" type="daterange" range-separator="–" start-placeholder="開始日" end-placeholder="終了日" format="YYYY/MM/DD" value-format="YYYY-MM-DD" :clearable="false" @change="applyCustomRange" /><el-button-group><el-button v-for="days in [7, 30, 90]" :key="days" :type="selectedDays === days ? 'primary' : 'default'" @click="setQuickRange(days)">{{ days }}日</el-button></el-button-group><el-button :loading="loading" circle aria-label="更新" @click="loadDashboard">↻</el-button></div></div>
    <p class="updated-at">最終更新：{{ lastUpdated ? formatDateTime(lastUpdated) : '—' }}</p>
    <div class="metric-grid"><MetricCard v-for="metric in metrics" :key="metric.label" v-bind="metric" :loading="loading" :error="hasError" /></div>
    <div v-if="hasError" class="page-error"><span>データを取得できませんでした。</span><el-button type="primary" size="small" @click="loadDashboard">再試行</el-button></div>
    <div class="content-grid">
      <article class="surface trend"><div class="surface-heading"><div><h2>売上推移</h2><p>日別の支払い済み売上高</p></div><span class="legend"><i />売上高</span></div><el-skeleton v-if="loading" animated :rows="8" /><div v-else-if="salesTrend.length" class="chart-content"><SalesTrendChart :data="salesTrend" /></div><div v-else class="empty">選択した期間の売上データはありません</div></article>
      <article class="surface category"><div class="surface-heading"><div><h2>カテゴリ別売上構成</h2><p>支払い済み売上高の構成比</p></div></div><el-skeleton v-if="loading" animated :rows="8" /><template v-else-if="categories.length"><CategoryDistributionChart :data="categories" /><ul class="category-legend"><li v-for="(category, index) in categories.slice(0, 5)" :key="category.categoryId"><i :style="{ background: colors[index] }" /><span>{{ category.categoryName }}</span><strong>{{ category.percentage.toFixed(1) }}%</strong></li></ul></template><div v-else class="empty">カテゴリデータはありません</div></article>
    </div>
    <div class="content-grid lower">
      <article class="surface"><div class="surface-heading"><div><h2>売れ筋商品</h2><p>売上高による上位5商品</p></div></div><el-skeleton v-if="loading" animated :rows="5" /><ol v-else-if="topProducts.length" class="ranking"><li v-for="(product, index) in topProducts" :key="product.productId"><span class="rank">{{ index + 1 }}</span><div><strong>{{ product.productName }}</strong><p>{{ product.categoryName }} · {{ product.quantitySold }}個</p></div><b>{{ formatMoney(product.revenue) }}</b></li></ol><div v-else class="empty">商品データはありません</div></article>
      <article class="surface"><div class="surface-heading"><div><h2>最近の注文</h2><p>選択期間内の直近8件</p></div></div><el-skeleton v-if="loading" animated :rows="5" /><div v-else-if="recentOrders.length" class="orders"><div v-for="order in recentOrders" :key="order.orderNumber" class="order-row"><div><strong>{{ order.orderNumber }}</strong><p>{{ order.customerName }} · {{ formatShortDate(order.createdAt) }}</p></div><span :class="['order-status', order.status.toLowerCase()]">{{ statusLabel(order.status) }}</span><b>{{ formatMoney(order.totalAmount) }}</b></div></div><div v-else class="empty">注文データはありません</div></article>
    </div>
  </section>
</template>

<script setup lang="ts">
import dayjs from 'dayjs';
import { computed, onMounted, ref } from 'vue';
import MetricCard from '../components/dashboard/MetricCard.vue';
import CategoryDistributionChart from '../components/charts/CategoryDistributionChart.vue';
import SalesTrendChart from '../components/charts/SalesTrendChart.vue';
import { getCategoryDistribution, getOverview, getRecentOrders, getSalesTrend, getTopProducts } from '../api/dashboard';
import type { CategoryDistribution, DashboardOverview, DateRangeParams, RecentOrder, SalesTrendPoint, TopProduct } from '../types/dashboard';

const today = dayjs(); const pickerRange = ref<[string, string]>([today.subtract(29, 'day').format('YYYY-MM-DD'), today.format('YYYY-MM-DD')]); const selectedDays = ref(30); const loading = ref(false); const hasError = ref(false); const lastUpdated = ref<Date | null>(null);
const overview = ref<DashboardOverview | null>(null); const salesTrend = ref<SalesTrendPoint[]>([]); const categories = ref<CategoryDistribution[]>([]); const topProducts = ref<TopProduct[]>([]); const recentOrders = ref<RecentOrder[]>([]);
const colors = ['#55cdf8', '#6d7dff', '#5cdbb0', '#f3b75f', '#c78cff'];
const metrics = computed(() => { const source = overview.value; return [{ label: '総売上高', value: formatMoney(source?.totalRevenue ?? 0), delta: source?.revenueGrowth ?? 0, description: '支払い済み注文の売上高' }, { label: '総注文数', value: formatNumber(source?.totalOrders ?? 0), delta: source?.orderGrowth ?? 0, description: '支払い済みの注文数' }, { label: '平均注文単価', value: formatMoney(source?.averageOrderValue ?? 0), delta: source?.revenueGrowth ?? 0, description: '支払い済み注文あたりの平均' }, { label: '新規顧客', value: formatNumber(source?.newCustomers ?? 0), delta: source?.customerGrowth ?? 0, description: '期間中に登録した顧客数' }]; });
function params(): DateRangeParams { return { startDate: pickerRange.value[0], endDate: pickerRange.value[1] }; }
async function loadDashboard(): Promise<void> { if (loading.value) return; loading.value = true; hasError.value = false; const query = params(); const results = await Promise.allSettled([getOverview(query), getSalesTrend(query), getCategoryDistribution(query), getTopProducts(query), getRecentOrders(query)]); const [overviewResult, trendResult, categoryResult, productsResult, ordersResult] = results; if (overviewResult.status === 'fulfilled') overview.value = overviewResult.value; if (trendResult.status === 'fulfilled') salesTrend.value = trendResult.value; if (categoryResult.status === 'fulfilled') categories.value = categoryResult.value; if (productsResult.status === 'fulfilled') topProducts.value = productsResult.value; if (ordersResult.status === 'fulfilled') recentOrders.value = ordersResult.value.items; hasError.value = results.some((result) => result.status === 'rejected'); if (!hasError.value) lastUpdated.value = new Date(); loading.value = false; }
function setQuickRange(days: number): void { selectedDays.value = days; pickerRange.value = [today.subtract(days - 1, 'day').format('YYYY-MM-DD'), today.format('YYYY-MM-DD')]; void loadDashboard(); }
function applyCustomRange(value: [string, string] | null): void { if (!value) return; selectedDays.value = 0; pickerRange.value = value; void loadDashboard(); }
function formatMoney(value: number): string { return new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY', maximumFractionDigits: 0 }).format(value); }
function formatNumber(value: number): string { return new Intl.NumberFormat('ja-JP').format(value); }
function formatDateTime(value: Date): string { return dayjs(value).format('YYYY/MM/DD HH:mm:ss'); }
function formatShortDate(value: string): string { return dayjs(value).format('MM/DD HH:mm'); }
function statusLabel(status: string): string { return ({ PENDING_PAYMENT: '支払い待ち', PAID: '支払い済み', PROCESSING: '処理中', SHIPPED: '発送済み', COMPLETED: '完了', CANCELLED: 'キャンセル', REFUNDED: '返金済み' } as Record<string, string>)[status] ?? status; }
onMounted(() => { void loadDashboard(); });
</script>

<style scoped>
.dashboard-page { padding-top: 22px; }.page-heading { display: flex; justify-content: space-between; align-items: flex-end; gap: 24px; margin: 22px 0 8px; }.overline { color: #4bc9f7; font-size: 11px; font-weight: 700; letter-spacing: .14em; }.page-heading h1 { margin: 8px 0; color: #eff8ff; font-size: 28px; letter-spacing: -.03em; }.page-heading > div > p:last-child, .updated-at { color: #7f9ab4; font-size: 13px; }.updated-at { margin: 0 0 20px; }.controls { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; }.controls :deep(.el-input__wrapper) { background: rgba(38, 79, 119, .2); box-shadow: 0 0 0 1px rgba(120,180,227,.18) inset; }.controls :deep(.el-range-input), .controls :deep(.el-range-separator) { color: #bed4e9; }.metric-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }.content-grid { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(300px, .9fr); gap: 16px; margin-top: 16px; }.content-grid.lower { grid-template-columns: repeat(2, minmax(0, 1fr)); }.surface { min-height: 328px; padding: 21px; border: 1px solid rgba(125,181,230,.13); border-radius: 13px; background: linear-gradient(135deg,rgba(24,50,82,.88),rgba(14,30,53,.88)); box-shadow: 0 15px 34px rgba(0,8,20,.18); }.surface-heading { display: flex; justify-content: space-between; align-items: flex-start; min-height: 42px; }.surface-heading h2 { margin: 0 0 5px; color: #eaf4fc; font-size: 15px; }.surface-heading p { color: #718ca7; font-size: 12px; }.legend { color: #83a3c0; font-size: 11px; }.legend i { display: inline-block; width: 7px; height: 7px; margin-right: 5px; border-radius: 50%; background: #48c8fa; }.empty { display: grid; min-height: 220px; place-items: center; color: #7894ad; font-size: 13px; }.category-legend { display: grid; gap: 7px; padding: 0; margin: 0; list-style: none; }.category-legend li { display: flex; gap: 8px; align-items: center; color: #9db6ca; font-size: 11px; }.category-legend i { width: 7px; height: 7px; border-radius: 50%; }.category-legend strong { margin-left: auto; color: #dbeaf6; font-size: 11px; }.ranking { padding: 7px 0 0; margin: 0; list-style: none; }.ranking li, .order-row { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-bottom: 1px solid rgba(126,174,218,.1); }.rank { display: grid; place-items: center; width: 23px; height: 23px; border-radius: 6px; color: #62d5fc; background: rgba(67,183,243,.11); font-size: 11px; font-weight: 700; }.ranking strong, .order-row strong { color: #dbeaf6; font-size: 12px; font-weight: 500; }.ranking p, .order-row p { margin: 4px 0 0; color: #738ea7; font-size: 11px; }.ranking b, .order-row b { margin-left: auto; color: #d9edf9; font-size: 12px; white-space: nowrap; }.order-status { margin-left: auto; padding: 3px 6px; border-radius: 5px; color: #9db5cc; background: rgba(110,148,184,.12); font-size: 10px; white-space: nowrap; }.order-status.completed, .order-status.paid { color: #49d6a2; background: rgba(59,201,149,.1); }.order-status.cancelled, .order-status.refunded { color: #ff9db0; background: rgba(250,112,140,.1); }.page-error { display: flex; justify-content: center; align-items: center; gap: 12px; min-height: 48px; margin-top: 16px; border: 1px solid rgba(255,142,162,.24); border-radius: 10px; color: #ffa0b3; background: rgba(150,46,71,.12); font-size: 13px; }
@media (max-width: 1150px) { .metric-grid { grid-template-columns: repeat(2, 1fr); } .content-grid { grid-template-columns: 1fr; } }
@media (max-width: 760px) { .page-heading { align-items: flex-start; flex-direction: column; }.controls { justify-content: flex-start; }.controls :deep(.el-date-editor) { width: 100%; }.content-grid.lower, .metric-grid { grid-template-columns: 1fr; }.surface { padding: 17px; }.order-row { gap: 8px; }.order-status { display: none; } }
</style>
